/* ChkLst01Mapper.selectChkptInspectItemList */ SELECT '' AS chk , A.CMPNY_CD AS cmpnyCd , A.CHKLST_TYPE AS chkLstType , A.INSPECT_ITEM_CD AS inspectItemCd , A.INSPECT_ITEM_SUBJ AS inspectItemSubj , A.SORT_IDX AS sortIdx , A.STR_DATE AS strDate , A.USE_YN AS useYn FROM TB_CHKPT_INSPECT_ITEM A WHERE 1=1 AND A.CMPNY_CD = #{gvCmpnyCd}
AND A.CHKLST_TYPE = #{codeCd}
ORDER BY CHKLST_TYPE, SORT_IDX

